import java.util.*;

class Solution {
    private int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};

    public List<String> findWords(char[][] board, String[] words) {
        // Build Trie
        int[][] trie = new int[200001][26];
        String[] endWord = new String[200001];
        int cnt = 1;

        for (String word : words) {
            int node = 0;
            for (char c : word.toCharArray()) {
                int idx = c - 'a';
                if (trie[node][idx] == 0) trie[node][idx] = cnt++;
                node = trie[node][idx];
            }
            endWord[node] = word;
        }

        List<String> result = new ArrayList<>();
        int m = board.length, n = board[0].length;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                dfs(board, i, j, 0, trie, endWord, result);
            }
        }
        return result;
    }

    private void dfs(char[][] board, int r, int c, int node, int[][] trie, String[] endWord, List<String> result) {
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) return;
        char ch = board[r][c];
        if (ch == '#' || trie[node][ch - 'a'] == 0) return;

        node = trie[node][ch - 'a'];
        if (endWord[node] != null) {
            result.add(endWord[node]);
            endWord[node] = null;
        }

        board[r][c] = '#';
        for (int[] d : dirs) dfs(board, r + d[0], c + d[1], node, trie, endWord, result);
        board[r][c] = ch;
    }
}
